class Node:
  def __init__(self, val):
    self.val = val
    self.next = None

class LinkedListStack:
  def __init__(self):
    self.head = None
    self._size = 0

  def push(self, val):
    new = Node(val)
    new.next = self.head
    self.head = new
    self._size += 1

  def pop(self):
    if not self.head:
      return None
    val = self.head.val
    self.head = self.head.next
    self._size -= 1
    return val

  def peek(self):
    if not self.head:
      return None
    return self.head.val

  def size(self):
    return self._size

  def empty(self):
    return self._size == 0

