class Node {
  int val;
  Node next;

  Node(int x) {
    val = x;
    next = null;
  }
}

class LinkedListStack {
  private Node head;
  private int size;

  public LinkedListStack() {
    head = null;
    size = 0;
  }

  public void push(int val) {
    Node newNode = new Node(val);
    newNode.next = head;
    head = newNode;
    size++;
  }

  public Integer pop() {
    if (head == null) {
      return null;
    }
    int val = head.val;
    head = head.next;
    size--;
    return val;
  }

  public Integer peek() {
    if (head == null) {
      return null;
    }
    return head.val;
  }

  public int size() {
    return size;
  }

  public boolean empty() {
    return size == 0;
  }
}

